<?php namespace App\Http\Controllers; use App\Http\Requests\InsurancePolicyRequest; use App\Models\{InsurancePolicy,Pet}; use Illuminate\Http\Request; class InsuranceController extends Controller { public function index(Request $r,Pet $pet){abort_unless($pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);return $pet->insurancePolicies()->latest()->get();} public function store(InsurancePolicyRequest $r){$pet=Pet::findOrFail($r->pet_id);abort_unless($pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);$data=$r->validated(); if($r->hasFile('document'))$data['document_path']=$r->file('document')->store('insurance','private');unset($data['document']);return InsurancePolicy::create($data);} public function update(InsurancePolicyRequest $r,InsurancePolicy $policy){abort_unless($policy->pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);$data=$r->validated(); if($r->hasFile('document'))$data['document_path']=$r->file('document')->store('insurance','private');unset($data['document']);$policy->update($data);return $policy;} public function destroy(Request $r,InsurancePolicy $policy){abort_unless($policy->pet->owner_id===$r->user()->id||$r->user()->role==='admin',403);$policy->delete();return response()->noContent();} }